    ])
    await expect(ctx.llm.listModels('deepseek')).resolves.toEqual([
      { provider: 'deepseek', id: 'flash', name: 'flash', inputModalities: ['text', 'image'] },
      { provider: 'deepseek', id: 'pro', name: 'Pro', description: 'Larger model' },
